package hk.local.enginex7;
import android.app.*;import android.content.*;import android.graphics.Bitmap;import android.os.*;import android.view.*;import android.widget.*;import android.location.Location;
import java.io.*;import java.util.*;import org.json.JSONObject;

public final class DeviceTests extends Instrumentation {
 private int count;private Bundle arguments;private MainActivity activity;private EngineService service;private File evidence;
 @Override public void onCreate(Bundle args){super.onCreate(args);arguments=args;start();}
 private void check(boolean ok,String name){if(!ok)throw new AssertionError(name);count++;}
 private void main(Runnable r){runOnMainSync(r);}
 private void pause(long n){SystemClock.sleep(n);}
 private View root(){return service.hasOverlay()?service.overlay:activity.getWindow().getDecorView();}
 private List<View> named(View v,String text){List<View> out=new ArrayList<>();if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))out.add(v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)out.addAll(named(g.getChildAt(i),text));}return out;}
 private void click(String text){main(()->{List<View> v=named(root(),text);if(v.isEmpty())throw new AssertionError("Missing control: "+text);if(!v.get(0).isEnabled())throw new AssertionError("Disabled control: "+text);v.get(0).performClick();});pause(450);}
 private List<Spinner> spinners(View v){List<Spinner> out=new ArrayList<>();if(v instanceof Spinner)out.add((Spinner)v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)out.addAll(spinners(g.getChildAt(i)));}return out;}
 private android.view.accessibility.AccessibilityNodeInfo node(android.view.accessibility.AccessibilityNodeInfo n,String text){if(n==null)return null;if(text.contentEquals(n.getText()==null?"":n.getText())&&n.isVisibleToUser()){android.graphics.Rect bounds=new android.graphics.Rect();n.getBoundsInScreen(bounds);if(!bounds.isEmpty())return n;}for(int i=0;i<n.getChildCount();i++){android.view.accessibility.AccessibilityNodeInfo found=node(n.getChild(i),text);if(found!=null)return found;}return null;}
 private void pick(String text)throws Exception{main(()->spinners(root()).get(0).performClick());android.view.accessibility.AccessibilityNodeInfo n=null;long end=SystemClock.elapsedRealtime()+3500;while(n==null&&SystemClock.elapsedRealtime()<end){pause(150);n=node(getUiAutomation().getRootInActiveWindow(),text);if(n==null)for(android.view.accessibility.AccessibilityWindowInfo w:getUiAutomation().getWindows()){n=node(w.getRoot(),text);if(n!=null)break;}}screenshot("engine-picker-open");check(n!=null,"engine picker opens: "+text);android.graphics.Rect r=new android.graphics.Rect();n.getBoundsInScreen(r);check(!r.isEmpty(),"picker item has visible bounds");long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,r.centerX(),r.centerY(),0);down.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);boolean delivered=getUiAutomation().injectInputEvent(down,true);down.recycle();pause(60);MotionEvent up=MotionEvent.obtain(now,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,r.centerX(),r.centerY(),0);up.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);delivered=getUiAutomation().injectInputEvent(up,true)&&delivered;up.recycle();check(delivered,"native picker touch delivered");String expected="";for(Profile p:Profile.ALL)if(p.name(service.config.english).equals(text))expected=p.id;long until=SystemClock.elapsedRealtime()+6000;while(!service.config.profileId.equals(expected)&&SystemClock.elapsedRealtime()<until)pause(100);}
 private void screenshot(String name)throws Exception{pause(600);Bitmap b=getUiAutomation().takeScreenshot();check(b!=null&&b.getWidth()>0,"screenshot "+name);try(FileOutputStream f=new FileOutputStream(new File(evidence,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();}
 private void waitAudio()throws Exception{long end=SystemClock.elapsedRealtime()+6000;while(!service.model.running&&SystemClock.elapsedRealtime()<end&&service.message.isEmpty())pause(100);check(service.model.running,"audio starts: "+service.message+" / "+service.audio.error);pause(2600);check(service.audio.ready&&service.audio.frames>48000,"PCM streaming");}
 @Override public void onStart(){Bundle result=new Bundle();try{android.accessibilityservice.AccessibilityServiceInfo info=getUiAutomation().getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;getUiAutomation().setServiceInfo(info);CoreTests.run();Intent launch=new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);getTargetContext().startActivity(launch);long launchUntil=SystemClock.elapsedRealtime()+8000;while((MainActivity.current.get()==null||EngineService.instance==null)&&SystemClock.elapsedRealtime()<launchUntil)pause(100);activity=MainActivity.current.get();pause(1300);service=EngineService.instance;check(service!=null,"foreground service exists");evidence=new File(getTargetContext().getFilesDir(),"qa");evidence.mkdirs();
  if(arguments!=null&&"vehicle".equals(arguments.getString("mode"))){vehicleProbe();}else if(arguments!=null&&"gps".equals(arguments.getString("mode"))){gpsProbe();}else if(arguments!=null&&"persist-set".equals(arguments.getString("mode"))){main(()->{service.config.internalDb=2;service.config.externalDb=-3;service.config.save();service.select("v10");});pause(800);check(!service.model.running,"persist does not start sound");}else if(arguments!=null&&"persist-check".equals(arguments.getString("mode"))){check(service.config.profileId.equals("v10"),"last sound survives process restart");check(service.config.internalDb==2&&service.config.externalDb==-3,"gain survives process restart");check(!service.model.running&&!service.audio.active(),"relaunch is silent");main(()->{service.select("subaru");service.config.internalDb=service.config.externalDb=0;service.config.save();service.exit();});}else if(arguments!=null&&"dropdown".equals(arguments.getString("mode"))){dropdownProbe();}else if(arguments!=null&&"shots".equals(arguments.getString("mode"))){shots();}else suite();
  JSONObject json=new JSONObject();json.put("result","PASS");json.put("coreAssertions",CoreTests.count);json.put("deviceAssertions",count);json.put("environment","Android 9 API28 x86 emulator");json.put("physicalCarVerified",false);json.put("mode",arguments==null?"suite":arguments.getString("mode","suite"));try(FileWriter w=new FileWriter(new File(evidence,"result.json"))){w.write(json.toString(2));}result.putString("result",json.toString());finish(0,result);
 }catch(Throwable e){try{screenshot("failure-"+(arguments==null?"suite":arguments.getString("mode","suite")));}catch(Throwable ignored){}result.putString("failure",e.toString()+"\n"+android.util.Log.getStackTraceString(e));finish(1,result);}}
 private void dropdownProbe()throws Exception{
  main(()->{service.stopEngine();service.config.english=false;service.config.output="internal";service.config.save();service.mode("sim");service.select("subaru");service.showOverlay(false);});pause(500);
  check(spinners(root()).get(0).getAdapter().getCount()==7,"all seven engine options available");
  for(Profile p:Profile.ALL){check(service.config.profileId.equals(p.id),"cycle reaches "+p.id);click("下一款聲效");}
  check(service.config.profileId.equals("subaru"),"cycle wraps to Subaru");click("上一款聲效");check(service.config.profileId.equals("boxer"),"previous reaches last preset");click("下一款聲效");screenshot("seven-engine-selector");
  click("設定");main(()->{for(Spinner s:spinners(root())){android.widget.SpinnerAdapter a=s.getAdapter();TextView selected=(TextView)a.getView(s.getSelectedItemPosition(),null,s);check(selected.getCurrentTextColor()==PanelView.TEXT&&((android.graphics.drawable.ColorDrawable)selected.getBackground()).getColor()==PanelView.SURFACE,"selected row has explicit readable colors");for(int i=0;i<a.getCount();i++){TextView item=(TextView)a.getDropDownView(i,null,s);check(item.getCurrentTextColor()==PanelView.TEXT&&((android.graphics.drawable.ColorDrawable)item.getBackground()).getColor()==PanelView.SURFACE,"every dropdown row has explicit readable colors");}}spinners(root()).get(0).performClick();});pause(300);
  check(node(getUiAutomation().getRootInActiveWindow(),"車外喇叭")!=null,"actual settings popup exposes option text");screenshot("settings-output-dropdown");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);pause(300);screenshot("settings-dropdown-closed");
  main(()->{service.removeOverlay();android.content.Context light=new android.view.ContextThemeWrapper(activity,android.R.style.Theme_Material_Light_NoActionBar);PanelView panel=new PanelView(light,service,new EngineService.Host(){public void floating(){}public void minimize(){}public void exit(){}public void permission(){}},false);panel.show(true);for(Spinner s:spinners(panel)){TextView v=(TextView)s.getAdapter().getDropDownView(0,null,s);check(v.getCurrentTextColor()==PanelView.TEXT&&((android.graphics.drawable.ColorDrawable)v.getBackground()).getColor()==PanelView.SURFACE,"light parent theme cannot wash out dropdown text");}service.exit();});pause(500);
 }
 private void suite()throws Exception{
  main(()->{service.removeOverlay();service.stopEngine();service.config.english=false;service.config.output="internal";service.config.internalDb=service.config.externalDb=0;service.config.save();service.mode("sim");service.select("subaru");activity.recreate();});pause(1300);activity=MainActivity.current.get();service=EngineService.instance;main(()->service.showOverlay(false));pause(500);
  check(service.overlay instanceof PanelView,"full panel overlay");check(!named(root(),"啟動引擎").isEmpty(),"Traditional Chinese default controls");pick("V10 · 尖叫");check(service.config.profileId.equals("v10"),"actual dropdown selects engine");pick(Profile.get("subaru").zh);check(service.config.profileId.equals("subaru"),"actual dropdown restores Subaru");screenshot("headunit-home");
  click("設定");check(!named(root(),"車內增益").isEmpty()&&!named(root(),"車外增益").isEmpty(),"two gain controls");main(()->{List<View> plus=named(root(),"+1 dB"),minus=named(root(),"−1 dB");check(plus.size()==2&&minus.size()==2,"independent gain buttons");plus.get(0).performClick();plus.get(0).performClick();minus.get(1).performClick();minus.get(1).performClick();minus.get(1).performClick();});pause(300);check(service.config.internalDb==2&&service.config.externalDb==-3,"independent +/- dB values");Config saved=new Config(getTargetContext());check(saved.internalDb==2&&saved.externalDb==-3,"gains persisted");screenshot("headunit-settings");
  main(()->{List<Spinner> all=spinners(root());Spinner output=all.get(0);output.setSelection(1);});pause(400);check(service.config.output.equals("external"),"external output selected");main(()->service.startEngine());pause(300);check(!service.model.running&&!service.message.isEmpty(),"missing external route rejected");main(()->spinners(root()).get(0).setSelection(2));pause(300);main(()->service.startEngine());pause(300);check(!service.model.running&&!service.message.isEmpty(),"Both unavailable not claimed successful");main(()->{spinners(root()).get(0).setSelection(0);service.message="";service.audio.error="";});pause(300);
  main(()->{List<Spinner> all=spinners(root());for(Spinner s:all)if(s.getAdapter().getItem(0).toString().equals("繁體中文"))s.setSelection(1);});pause(700);check(service.config.english&&!named(root(),"Internal gain").isEmpty(),"English language switch");check(new Config(getTargetContext()).english,"language persisted");click("Back");main(()->spinners(root()).get(0).setSelection(4));pause(300);check(service.config.profileId.equals("v10")&&new Config(getTargetContext()).profileId.equals("v10"),"last sound selection persisted");main(()->spinners(root()).get(0).setSelection(0));pause(300);
  click("Start engine");waitAudio();check(service.model.frame.rpm>=service.model.profile.idle&&service.model.frame.gear==0,"idle at zero pedal");check(service.audio.internalRouted>=0&&service.audio.externalRouted==-1,"actual internal route only");
  main(()->{service.model.pedal=1;});pause(4500);check(service.model.frame.speed>10&&service.audio.peak>.001,"driving produces real PCM");screenshot("headunit-driving");long frames=service.audio.frames;click("Minimize");check(service.minimized&&!(service.overlay instanceof PanelView),"minimized overlay");screenshot("minimized");View restoreView=named(root(),"7X · Restore").get(0),exitView=named(root(),"Exit").get(0);check(exitView.getLeft()-restoreView.getRight()>=8*getTargetContext().getResources().getDisplayMetrics().density,"minimized touch targets have at least 8dp gap");pause(1800);check(service.model.running&&service.audio.frames>frames+48000,"background audio keeps advancing");click("7X · Restore");check(!service.minimized&&service.overlay instanceof PanelView,"overlay restored");main(()->service.model.pedal=0);pause(1000);click("Stop engine");pause(500);check(!service.model.running&&!service.audio.active(),"stop releases audio");
  main(()->{service.mode("gps");service.startEngine();});waitAudio();long now=SystemClock.elapsedRealtimeNanos();main(()->{service.input.stop();Location l=new Location("gps");l.setLatitude(22.3);l.setLongitude(114.17);l.setAccuracy(4);l.setSpeed(12);l.setElapsedRealtimeNanos(now);service.input.onLocationChanged(l);});pause(150);check(service.input.fresh()&&service.model.frame.speed>11,"synthetic Android GPS location consumed");pause(3200);check(!service.input.fresh()&&service.model.frame.speed==0,"GPS expiry idle fallback");main(()->service.stopEngine());pause(500);
  main(()->{service.config.english=false;service.config.internalDb=0;service.config.externalDb=0;service.config.output="internal";service.config.save();service.select("subaru");service.mode("sim");service.showOverlay(false);});pause(500);click("啟動引擎");waitAudio();click("退出");pause(1000);check(EngineService.instance==null,"Exit destroys service");check(!service.audio.active()&&!service.hasOverlay(),"Exit removes audio and overlays");
 }
 private void shots()throws Exception{main(()->{service.stopEngine();service.config.english=false;service.config.output="internal";service.config.save();service.mode("sim");service.showOverlay(false);});pause(500);screenshot("compact-home-font130");click("設定");screenshot("compact-settings-font130");main(()->{service.config.english=true;service.config.save();((PanelView)service.overlay).show(true);});pause(300);screenshot("compact-settings-en-font130");main(()->{service.config.english=false;service.config.save();service.exit();});pause(500);}
 private void live(double t,double b,double s,int sw,long duration){long end=SystemClock.elapsedRealtime()+duration;while(SystemClock.elapsedRealtime()<end){main(()->{long now=SystemClock.elapsedRealtime();service.vehicle.snapshot=new VehicleSnapshot(t,now,b,now,s,now,sw,now);service.vehicle.status="fixture";});pause(40);}}
 private void captureLive(String name,double t,double b,double s,int sw)throws Exception{java.util.concurrent.atomic.AtomicBoolean active=new java.util.concurrent.atomic.AtomicBoolean(true);Thread pump=new Thread(()->{while(active.get()){long now=SystemClock.elapsedRealtime();service.vehicle.snapshot=new VehicleSnapshot(t,now,b,now,s,now,sw,now);service.vehicle.status="fixture";SystemClock.sleep(40);}},"QA-only-telemetry");pump.start();try{screenshot(name);}finally{active.set(false);pump.join(1000);}}
 private void vehicleProbe()throws Exception{
  main(()->{service.stopEngine();service.vehicle.stop();service.config.english=false;service.config.output="internal";service.config.internalDevice="";service.config.internalDb=service.config.externalDb=0;service.config.sampleRate=44100;service.config.save();service.mode("vehicle");service.select("subaru");service.showOverlay(false);});pause(500);screenshot("ecarx-unavailable");
  main(()->service.startEngine());waitAudio();check(service.model.profile.id.equals("subaru"),"vehicle/BOV fixture explicitly selects Subaru");check(!service.input.listening,"vehicle mode does not start or require GPS");live(61,0,0,0,1000);check(service.model.frame.rpm>2500&&service.model.frame.speed==0,"stationary real-pedal fixture changes RPM without GPS or fake speed: rpm="+service.model.frame.rpm+" load="+service.model.frame.load);long ticksBefore=service.ticks,framesBefore=service.audio.frames;main(()->SystemClock.sleep(600));check(service.ticks>ticksBefore+8,"model ticks continue while UI thread is blocked");check(service.audio.frames>framesBefore+service.audio.rate/4,"PCM continues while UI thread is blocked");captureLive("ecarx-pedal-61",61,0,0,0);
  live(100,0,0,0,800);check(service.model.frame.rpm>5500,"100 percent reaches high virtual RPM");int bov=service.model.frame.bovSerial;live(0,0,0,0,900);check(service.model.frame.bovSerial>bov,"live release triggers BOV");
  live(61,0,11.111111,0,800);check(Math.abs(service.model.frame.speed*3.6-40)<.01,"actual-speed fixture follows ECARX m/s");live(61,14.84375,11.111111,1,1500);check(service.model.frame.load<.02,"live brake fixture overrides throttle: load="+service.model.frame.load);captureLive("ecarx-brake",61,14.84375,11.111111,1);long staleDeadline=SystemClock.elapsedRealtime()+2600;while((service.vehicle.snapshot.throttleFresh(SystemClock.elapsedRealtime())||service.model.frame.rpm>=service.model.profile.idle+5)&&SystemClock.elapsedRealtime()<staleDeadline)pause(40);check(!service.vehicle.snapshot.throttleFresh(SystemClock.elapsedRealtime())&&service.model.frame.rpm<service.model.profile.idle+5,"ECARX stale fallback reaches idle within bounded expiry/ramp window");screenshot("ecarx-stale");main(()->service.stopEngine());pause(500);
  click("設定");main(()->service.testSpeaker("internal"));pause(700);check(service.audio.testActive&&service.audio.frames>0&&service.audio.playedFrames>0&&!service.model.running,"independent 44.1k stereo speaker test advances playback without engine");check(service.audio.activeOutput.equals("internal")&&service.audio.lastWasTest,"test target is independent from saved output");check(!named(root(),"停止試音").isEmpty()&&named(root(),"停止試音").get(0).getVisibility()==View.VISIBLE,"visible nearby test stop control");screenshot("speaker-test");pause(2800);check(!service.audio.active()&&!service.testing,"speaker test ends and releases track");screenshot("speaker-test-complete");
  main(()->{service.config.sampleRate=48000;service.config.save();service.testSpeaker("internal");});pause(700);check(service.audio.rate==48000&&service.audio.playedFrames>0,"48k stereo alternative streams");pause(2800);main(()->service.testSpeaker("internal"));pause(400);click("停止試音");pause(500);check(!service.audio.active()&&service.audio.testCancelled,"visible Stop test stops speaker test");screenshot("speaker-test-stopped");main(()->service.testSpeaker("external"));pause(300);check(!service.audio.active()&&!service.message.isEmpty(),"unavailable BUS12 is visible for independent speaker test");check(service.audio.activeOutput.equals("external"),"failed exterior test retains actual test target");screenshot("audio-error");main(()->{service.config.sampleRate=44100;service.config.save();service.exit();});pause(400);
 }
 private void gpsProbe()throws Exception{main(()->{service.removeOverlay();service.stopEngine();service.config.english=false;service.config.output="internal";service.config.save();service.mode("gps");service.showOverlay(false);service.startEngine();});waitAudio();long end=SystemClock.elapsedRealtime()+25000;while(!service.input.fresh()&&SystemClock.elapsedRealtime()<end)pause(300);check(service.input.listening,"GPS listener active");check(service.input.fresh(),"emulator GPS fix received");screenshot("emulator-gps");click("定位權限／GPS 設定");check(service.minimized&&service.hasOverlay(),"GPS settings minimizes overlay");click("7X · 還原");main(()->service.stopEngine());pause(500);}
}
